import{c as e,J as r,h as a,k as o}from"./chunks/framework.WgZQdPFo.js";const c=JSON.parse('{"title":"Сводка капитала (Net Worth)","description":"Консолидированная инфопанель общего благосостояния мастера, объединяющая личные финансы и производственный капитал всех мастерских.","frontmatter":{"title":"Сводка капитала (Net Worth)","description":"Консолидированная инфопанель общего благосостояния мастера, объединяющая личные финансы и производственный капитал всех мастерских.","order":21},"headers":[],"relativePath":"ru/docs/spaces/moy-kapital/dashboard.md","filePath":"ru/docs/spaces/moy-kapital/dashboard.md"}'),s={name:"ru/docs/spaces/moy-kapital/dashboard.md"};function l(n,t,d,i,h,p){return r(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="сводка-капитала-net-worth" tabindex="-1">Сводка капитала (Net Worth) <a class="header-anchor" href="#сводка-капитала-net-worth" aria-label="Permalink to &quot;Сводка капитала (Net Worth)&quot;">​</a></h1><p>Вкладка <strong>«Сводка капитала»</strong> — это главный командный пункт мастера в пространстве «Мой капитал». Она собирает данные со всех уголков экосистемы ОмниКрафт ЕРП и формирует единую, кристально ясную картину: <strong>сколько на самом деле стоит все Ваше дело и личное имущество прямо сейчас</strong>.</p><hr><h2 id="формула-совокупного-капитала-net-worth" tabindex="-1">Формула совокупного капитала (Net Worth) <a class="header-anchor" href="#формула-совокупного-капитала-net-worth" aria-label="Permalink to &quot;Формула совокупного капитала (Net Worth)&quot;">​</a></h2><p>Показатель <strong>Net Worth (Чистая стоимость капитала)</strong> вычисляется по строгой математической формуле:</p><p>$$\\text{Net Worth} = \\text{Ликвидные счета} + \\text{Инвестиционный портфель} + \\text{Имущество} + \\sum \\text{Капитал мастерских}$$</p><p>Инфопанель разбита на четыре фундаментальных блока:</p><ol><li><strong>Ликвидный капитал:</strong> доступные денежные средства на всех банковских картах, вкладах, кошельках и стейблкоинах, приведенные к базовой валюте.</li><li><strong>Инвестиционный капитал:</strong> рыночная стоимость портфеля ценных бумаг, криптовалют, займов и долей за вычетом первоначальных вложений ($P&amp;L$).</li><li><strong>Материальные активы:</strong> рыночная оценка долгосрочного оборудования, станков, недвижимости и транспорта с учетом долей владения.</li><li><strong>Производственный капитал бизнесов:</strong> сумма чистых активов во всех зарегистрированных рабочих пространствах: $$\\text{Капитал цеха} = \\text{Остаток ДДС (Касса)} + \\text{Склад сырья (MAC)} + \\text{Заказы в работе} + \\text{Склад готовой продукции (FIFO)}$$</li></ol><div class="info custom-block"><p class="custom-block-title">Мгновенная консолидация мультипространств</p><p>Если вы ведете три независимых направления (например, кожевенную мастерскую, продажу лекал и курсы ремесла), сводка автоматически прочитает файлы баз данных каждого цеха и сложит их реальный капитал в общую сумму без необходимости переключать пространства.</p></div><hr><h2 id="расчет-непривязанных-расходов-цеха" tabindex="-1">Расчет непривязанных расходов цеха <a class="header-anchor" href="#расчет-непривязанных-расходов-цеха" aria-label="Permalink to &quot;Расчет непривязанных расходов цеха&quot;">​</a></h2><p>В нижней секции сводки представлена аналитическая карточка балансовой дельты. Она сопоставляет финансовые результаты за выбранный месяц:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Показатель</th><th style="text-align:left;">Источник данных</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Совокупный доход мастера</strong></td><td style="text-align:left;">Чистая прибыль цехов + дивиденды + внешние доходы</td></tr><tr><td style="text-align:left;"><strong>Изменение капитала (Дельта)</strong></td><td style="text-align:left;">$\\text{Net Worth}<em>{\\text{кон}} - \\text{Net Worth}</em>{\\text{нач}}$</td></tr><tr><td style="text-align:left;"><strong>Непривязанные личные расходы</strong></td><td style="text-align:left;">$\\text{Доходы} - \\text{Дельта капитала}$</td></tr></tbody></table><p>Если мастерская заработала $200,000\\text{ ₽}$, а совокупный капитал за месяц вырос только на $80,000\\text{ ₽}$, программа делает однозначный вывод: $120,000\\text{ ₽}$ ушли на повседневную жизнь, семью и мелкие бытовые нужды.</p><p>Вам больше не нужно вести учет каждой пачки молока: дельта капитала делает это за Вас автоматически и с точностью до копейки.</p>',15)])])}const g=e(s,[["render",l]]);export{c as __pageData,g as default};
